"""Synthetic paired sim-to-field records, generated by this module and nothing else.

No measurement of any real aircraft, engine or test article appears anywhere in
this repository. Every number in ``validation/`` is measured against records
produced here, from a declared seed, by a committed script. The purpose of the
generator is to make the TRUE discrepancy distribution known, so that a bound
can be scored on whether it actually covers rather than on whether it looks
reasonable.

The scenario
------------
A digital twin of a transport-aircraft wing predicts the **wing-root bending
moment** at a given operating condition; a flight test measures the same
quantity with a calibrated strain channel. The discrepancy is in **kN.m**.
The channel's calibrated range gives the declared ``R`` of equation (1):
:data:`BOUND_RANGE_KNM`, 40 kN.m.

The truth model, stated so it can be argued with
------------------------------------------------
Operating condition ``x = (mach, altitude_km, alpha_deg, load_factor)``. The
raw signed twin error is

    e(x) = b(x) + s(x) Z,     Z ~ Normal(0, 1),                          (19)
    b(x) = B0 + B1 sigma((M - M_b)/W_b) + B2 (alpha / 10)^2,             (20)
    s(x) = S0 + S1 sigma((M - M_s)/W_s) + S2 (nz - 1),                   (21)

with ``sigma(u) = 1/(1 + exp(-u))`` and the constants of
:data:`TRUTH_CONSTANTS`. The observable discrepancy is
``d = min(|e(x)|, R)`` by equation (1).

This is a **declared fiction with an engineering shape**, not a physical
derivation, and it is labelled as such everywhere it is used. What it encodes
is the one qualitative fact that makes this problem interesting: a twin's
error is not uniform over the envelope. Equations (20) and (21) put the growth
in the transonic corner, because a steady linear-aerodynamics twin loses
fidelity as shock formation begins, and add a quadratic growth with angle of
attack. The specific constants are chosen so that the mean discrepancy is a
few per cent of ``R`` and the upper tail reaches a substantial fraction of it,
which is the regime where the choice of bound actually matters. Nothing in
:mod:`transfergap.bounds` knows any of this: the distribution-free bounds see
only ``d`` and ``R``.

Two campaign shapes
-------------------
``"random"``
    Operating conditions drawn independently from the envelope. The
    discrepancies are i.i.d. and therefore exchangeable.

``"swept"``
    Mach swept monotonically across the index, as a flight-test card is
    actually flown, with the other conditions drawn independently. The
    discrepancies are independent but **not** exchangeable in the index: their
    distribution depends on where in the campaign they sit. This is the
    deliberately non-exchangeable set that
    ``validation/validate_exchangeability_output.txt`` reports on.
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

from .discrepancy import GapSample

__all__ = [
    "BOUND_RANGE_KNM",
    "CAMPAIGNS",
    "ENVELOPE",
    "FEATURE_NAMES",
    "TRUTH_CONSTANTS",
    "UNIT",
    "conditional_mean_gap",
    "generate",
    "population_truth",
    "sample_conditions",
]

#: Unit of every discrepancy in this package's synthetic data.
UNIT = "kN.m"

#: The declared range ``R`` of equation (1): the strain channel's calibrated
#: full scale. A discrepancy above this is censored, not measured.
BOUND_RANGE_KNM = 40.0

#: Operating-condition names, in column order.
FEATURE_NAMES: tuple[str, ...] = ("mach", "altitude_km", "alpha_deg", "load_factor")

#: The declared operating envelope: (low, high) per feature, in column order.
#: Mach and load factor are dimensionless, altitude is in km, angle of attack
#: in degrees.
ENVELOPE: tuple[tuple[float, float], ...] = (
    (0.55, 0.95),
    (6.0, 12.0),
    (0.0, 9.0),
    (0.8, 3.0),
)

#: The constants of equations (20) and (21). Units: B0, B1, B2, S0, S1, S2 in
#: kN.m; M_b, M_s, W_b, W_s dimensionless Mach number.
TRUTH_CONSTANTS: dict[str, float] = {
    "B0": 2.0,
    "B1": 6.0,
    "M_b": 0.82,
    "W_b": 0.05,
    "B2": 3.0,
    "S0": 1.5,
    "S1": 4.0,
    "M_s": 0.85,
    "W_s": 0.04,
    "S2": 1.0,
}

#: The two campaign shapes.
CAMPAIGNS: tuple[str, ...] = ("random", "swept")


def _sigmoid(value: np.ndarray) -> np.ndarray:
    """Logistic function, numerically safe for large negative arguments."""
    return 0.5 * (1.0 + np.tanh(0.5 * value))


def _bias(features: np.ndarray) -> np.ndarray:
    """``b(x)`` of equation (20), kN.m."""
    k = TRUTH_CONSTANTS
    mach = features[:, 0]
    alpha = features[:, 2]
    return (
        k["B0"]
        + k["B1"] * _sigmoid((mach - k["M_b"]) / k["W_b"])
        + k["B2"] * (alpha / 10.0) ** 2
    )


def _scale(features: np.ndarray) -> np.ndarray:
    """``s(x)`` of equation (21), kN.m. Strictly positive over the envelope."""
    k = TRUTH_CONSTANTS
    mach = features[:, 0]
    load = features[:, 3]
    return k["S0"] + k["S1"] * _sigmoid((mach - k["M_s"]) / k["W_s"]) + k["S2"] * (load - 1.0)


def conditional_mean_gap(features: np.ndarray) -> np.ndarray:
    """``E[d | x]`` for equations (19)-(21), ignoring the clip at ``R``, kN.m.

    For ``e ~ Normal(b, s)`` the folded normal has mean

        E|e| = s sqrt(2/pi) exp(-b^2 / (2 s^2)) + b (1 - 2 Phi(-b/s)),    (22)

    which is the standard folded-normal mean (Leone, F. C., Nelson, L. S. and
    Nottingham, R. B. (1961), "The folded normal distribution", *Technometrics*
    3(4), 543-550, equation 2). This is the **conditional truth** the learned
    model is trying to estimate, and it is available here only because the
    generator is synthetic. The clip at ``R`` is neglected: over this envelope
    the probability of exceeding ``R`` is below 1e-6 and
    ``validation/validate_learned_model_output.txt`` reports the measured clip
    fraction so the neglect can be checked rather than trusted.
    """
    from scipy import stats

    array = np.asarray(features, dtype=np.float64)
    if array.ndim != 2 or array.shape[1] != len(FEATURE_NAMES):
        raise ValueError(
            f"features must have shape (n, {len(FEATURE_NAMES)}); got {array.shape}"
        )
    bias = _bias(array)
    scale = _scale(array)
    ratio = bias / scale
    return scale * np.sqrt(2.0 / np.pi) * np.exp(-0.5 * ratio**2) + bias * (
        1.0 - 2.0 * stats.norm.cdf(-ratio)
    )


def sample_conditions(n: int, campaign: str, rng: np.random.Generator) -> np.ndarray:
    """``(n, 4)`` operating conditions for a campaign shape.

    ``"random"`` draws every column independently and uniformly from
    :data:`ENVELOPE`. ``"swept"`` replaces the Mach column by a monotone sweep
    across the index with a small uniform jitter, which is what makes the
    resulting discrepancies non-exchangeable in the index.
    """
    count = int(n)
    if count < 1:
        raise ValueError(f"n must be at least 1; got {n}")
    if campaign not in CAMPAIGNS:
        raise ValueError(f"campaign must be one of {list(CAMPAIGNS)}; got {campaign!r}")
    columns = [rng.uniform(low, high, size=count) for low, high in ENVELOPE]
    if campaign == "swept":
        low, high = ENVELOPE[0]
        step = (high - low) / max(count, 1)
        columns[0] = np.clip(
            np.linspace(low, high, count, endpoint=False)
            + rng.uniform(0.0, step, size=count),
            low,
            high,
        )
    return np.column_stack(columns)


def generate(
    n: int,
    campaign: str = "random",
    seed: int = 0,
    bound_range: float = BOUND_RANGE_KNM,
) -> GapSample:
    """A synthetic paired sim-to-field record of ``n`` measurements.

    Parameters
    ----------
    n:
        Number of paired measurements.
    campaign:
        ``"random"`` (exchangeable) or ``"swept"`` (not exchangeable in the
        index).
    seed:
        Seed for ``numpy.random.default_rng``. Regeneration is deterministic.
    bound_range:
        The declared ``R``, kN.m.

    Returns
    -------
    GapSample
        Discrepancies in kN.m with their operating conditions.
    """
    rng = np.random.default_rng(int(seed))
    features = sample_conditions(n, campaign, rng)
    raw = _bias(features) + _scale(features) * rng.standard_normal(features.shape[0])
    gaps = np.minimum(np.abs(raw), float(bound_range))
    return GapSample(
        gaps=gaps,
        features=features,
        feature_names=FEATURE_NAMES,
        unit=UNIT,
        bound_range=float(bound_range),
    )


@dataclass(frozen=True)
class PopulationTruth:
    """The true discrepancy population of the ``"random"`` campaign.

    Attributes
    ----------
    mean:
        ``E[d]``, kN.m, by Monte Carlo at :attr:`draws`.
    quantiles:
        Mapping of proportion to the true population quantile of ``d``, kN.m.
    clip_fraction:
        Fraction of draws whose raw discrepancy exceeded ``R`` and was
        censored by equation (1).
    draws:
        Monte Carlo size.
    seed:
        The declared seed.
    standard_error:
        Monte Carlo standard error of :attr:`mean`, kN.m. Reported so that no
        comparison against the truth is made tighter than the truth is known.
    """

    mean: float
    quantiles: dict[float, float]
    clip_fraction: float
    draws: int
    seed: int
    standard_error: float


def population_truth(
    proportions: tuple[float, ...] = (0.90, 0.95, 0.99),
    draws: int = 400_000,
    seed: int = 20260101,
    bound_range: float = BOUND_RANGE_KNM,
) -> PopulationTruth:
    """The true mean and quantiles of the discrepancy population, by Monte Carlo.

    This is the reference every coverage number in this repository is scored
    against. It exists only because the data is synthetic; a real campaign has
    no such reference, which is the entire reason the bounds in this package
    have to be distribution-free.

    At the default ``draws = 400000`` the standard error of the mean is about
    0.006 kN.m against a mean of a few kN.m, and it is returned rather than
    assumed so that a coverage comparison is never stated tighter than the
    truth is known.
    """
    rng = np.random.default_rng(int(seed))
    features = sample_conditions(int(draws), "random", rng)
    raw = _bias(features) + _scale(features) * rng.standard_normal(features.shape[0])
    absolute = np.abs(raw)
    gaps = np.minimum(absolute, float(bound_range))
    return PopulationTruth(
        mean=float(np.mean(gaps)),
        quantiles={
            float(p): float(np.quantile(gaps, p)) for p in proportions
        },
        clip_fraction=float(np.mean(absolute > float(bound_range))),
        draws=int(draws),
        seed=int(seed),
        standard_error=float(np.std(gaps, ddof=1) / np.sqrt(draws)),
    )
